import pytest

from boxyard import const
from boxyard._enums import BoxPart
from boxyard._fingerprint import base_path_for
from boxyard._models import SyncRecord, get_boxyard_meta
from boxyard._sync_policy import meta_provably_unchanged, project_record_listing
from boxyard.cmds import modify_boxmeta, new_box


def _make_box(config_path, remote_name, name):
    return new_box(
        config_path=config_path,
        box_name=name,
        storage_location=remote_name,
        verbose=False,
        claim=False,
    )


def _run(config_path, *args):
    from typer.testing import CliRunner

    from boxyard._cli.app import app

    result = CliRunner().invoke(
        app, ["--config", str(config_path), "multi-sync", *args]
    )
    assert result.exit_code == 0, f"exited {result.exit_code}\n{result.output}"
    return result


def _views(remote_root):
    """What the bulk `sync_records/` listing projects to, from the disk the
    alias remote points at."""
    rec_root = remote_root / "boxyard" / const.SYNC_RECORDS_REL_PATH
    entries = []
    for box_dir in rec_root.iterdir():
        for f in box_dir.iterdir():
            if f.is_file():
                entries.append({"Path": f"{box_dir.name}/{f.name}"})
    return project_record_listing(entries)


def _meta(config, index_name):
    return get_boxyard_meta(config).by_index_name[index_name]

# %% pts/tests/integration/cmds/test_meta_skip_filter.pct.py 4
class RemoteCallCounter:
    def __init__(self, monkeypatch):
        import boxyard._utils.rclone as rclone_module

        self.calls = []
        self._original = rclone_module.run_cmd_async

        async def _counting(cmd, *args, **kwargs):
            self.calls.append(cmd)
            return await self._original(cmd, *args, **kwargs)

        monkeypatch.setattr(rclone_module, "run_cmd_async", _counting)

    def __len__(self):
        return len(self.calls)

# %% pts/tests/integration/cmds/test_meta_skip_filter.pct.py 6
def test_the_filter_collapses_a_clean_pass(temp_boxyard, monkeypatch):
    """
    With nothing changed on either side, a filtered META pass must cost far
    less than an unfiltered one. If this ever regresses, the whole point of
    the fast loop is gone and it is back to ~6.6 min on the real yard.
    """
    remote_name, _, config, config_path, _ = temp_boxyard
    for i in range(5):
        _make_box(config_path, remote_name, f"box-{i}")

    # Sync once so both sides agree and every baseline exists.
    _run(config_path, "-c", "meta")
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    unfiltered = RemoteCallCounter(monkeypatch)
    _run(config_path, "-c", "meta")
    unfiltered_calls = len(unfiltered)

    filtered = RemoteCallCounter(monkeypatch)
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")
    filtered_calls = len(filtered)

    print(
        f"\n  5 boxes, nothing changed: "
        f"unfiltered={unfiltered_calls} remote calls, "
        f"filtered={filtered_calls}"
    )
    assert unfiltered_calls > 0, "the counter caught nothing -- it is vacuous"
    # The filter's cost is a FIXED few listings; the unfiltered pass grows with
    # the box count. Asserting a ratio rather than "fewer" keeps the test
    # meaningful: on the real 590-box yard this is ~1,180 calls against ~3.
    assert filtered_calls <= unfiltered_calls / 2, (
        f"the filter saved only {unfiltered_calls - filtered_calls} of "
        f"{unfiltered_calls} calls; expected at least half"
    )

# %% pts/tests/integration/cmds/test_meta_skip_filter.pct.py 8
def test_an_unchanged_box_is_provable(temp_boxyard):
    """The positive case -- without it the tests below could all pass vacuously."""
    remote_name, remote_root, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "quiet-box")
    _run(config_path, "-c", "meta")
    assert meta_provably_unchanged(config, _meta(config, index_name), _views(remote_root)[index_name])


def test_a_local_meta_edit_is_never_provable(temp_boxyard):
    """
    A local edit must reach the remote even though the remote has not moved.
    This is the half a naive remote-only filter would silently drop -- fast
    inbox, dead outbox.
    """
    remote_name, remote_root, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "edited-box")
    _run(config_path, "-c", "meta")
    assert meta_provably_unchanged(config, _meta(config, index_name), _views(remote_root)[index_name])

    modify_boxmeta(
        config_path=config_path,
        box_index_name=index_name,
        modifications={"groups": ["a-new-group"]},
    )
    assert not meta_provably_unchanged(config, _meta(config, index_name), _views(remote_root)[index_name])


def test_a_box_missing_from_the_listing_is_never_provable(temp_boxyard):
    """
    Absent from the bulk listing means new here, deleted there, or on a storage
    location the listing did not cover. Every one of those wants the real sync
    path to look.
    """
    remote_name, _, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "ghost-box")
    _run(config_path, "-c", "meta")
    assert not meta_provably_unchanged(config, _meta(config, index_name), None)


def test_a_box_with_no_baseline_is_never_provable(temp_boxyard):
    """
    No baseline means "cannot tell whether there is a local edit", which must
    cost a sync rather than skip one. This is what makes the upgrade safe:
    every box is checked once, then settles.
    """
    remote_name, remote_root, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "baseless-box")
    _run(config_path, "-c", "meta")

    meta = _meta(config, index_name)
    base = base_path_for(meta.get_local_sync_record_path(config, BoxPart.META))
    assert base.exists()
    base.unlink()
    assert not meta_provably_unchanged(config, meta, _views(remote_root)[index_name])


def test_a_remote_record_rewritten_elsewhere_is_never_provable(temp_boxyard):
    """
    What another machine's push leaves behind: a new remote record with a new
    ULID and its marker. This machine's local record still names the old one,
    so the identities differ and the box is needed -- whenever the push landed.
    """
    remote_name, remote_root, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "pushed-elsewhere")
    _run(config_path, "-c", "meta")
    meta = _meta(config, index_name)
    assert meta_provably_unchanged(config, meta, _views(remote_root)[index_name])

    import asyncio

    foreign = SyncRecord.create(sync_complete=True, syncer_hostname="another-machine")
    asyncio.run(foreign.rclone_save(
        str(config.rclone_config_path), remote_name,
        meta.get_remote_sync_record_path(config, BoxPart.META).as_posix(),
    ))
    assert not meta_provably_unchanged(config, meta, _views(remote_root)[index_name])


def test_a_box_whose_sync_failed_stays_needed(temp_boxyard, monkeypatch):
    """
    The most dangerous wrong answer this filter could give would be to record
    a reconciliation that never happened. Nothing is stamped any more, but the
    marker BOOTSTRAP is a write the real path makes after a pass -- so it must
    not happen for a box whose sync errored, or a moved remote could be
    published as agreed. Constructed so the outcomes are distinguishable:
    strip the box's marker, move the remote on, then fail the sync.
    """
    import boxyard.cmds as cmds_module

    remote_name, remote_root, config, config_path, _ = temp_boxyard
    index_name = _make_box(config_path, remote_name, "doomed-box")
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")
    meta = _meta(config, index_name)

    rec_dir = remote_root / "boxyard" / const.SYNC_RECORDS_REL_PATH / index_name
    for marker in rec_dir.glob("meta.rec.*"):
        marker.unlink()
    assert not meta_provably_unchanged(config, meta, _views(remote_root)[index_name])

    async def _explode(*args, **kwargs):
        raise RuntimeError("remote went away")

    monkeypatch.setattr(cmds_module, "sync_box", _explode)
    _run(config_path, "-c", "meta", "--skip-unchanged-meta")

    assert list(rec_dir.glob("meta.rec.*")) == [], (
        "a box whose sync FAILED had a marker published for it; it would now "
        "be skipped on every future pass"
    )
    assert not meta_provably_unchanged(config, meta, _views(remote_root)[index_name])
